# v9-patch.ps1 - Arus Global v9 (panel 1-5) untuk tools\v8.js dan public\index.html
$ErrorActionPreference = 'Stop'
Set-Location 'E:\0\MAB Project\MAB-Terminal\mab-terminal'
$b64 = ''
$blk = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64)).Replace("`r`n","`n").TrimEnd()
$jsPath = (Resolve-Path 'tools\v8.js').Path
$htPath = (Resolve-Path 'public\index.html').Path
$js = [IO.File]::ReadAllText($jsPath).Replace("`r`n","`n")
$ht = [IO.File]::ReadAllText($htPath).Replace("`r`n","`n")
if ($js.Contains('function flowNew')) { 'Sudah ditambal sebelumnya. Tidak ada yang diubah.'; return }
function Rep([string]$t,[string]$old,[string]$new){
  $n = ([regex]::Matches($t,[regex]::Escape($old))).Count
  if ($n -ne 1) { throw "Anchor harus cocok tepat 1 kali, ditemukan $n : $old" }
  return $t.Replace($old,$new)
}
$dash = [string][char]0x2014
$js2 = $js
$js2 = Rep $js2 "mode:'swing',view:'tabel'}" "mode:'swing',view:'tabel',ftf:'m15'}"
$js2 = Rep $js2 "const PAGES={" ($blk + "`n" + "const PAGES={")
$js2 = Rep $js2 "flow:()=>{const G6=" ("flow:()=>flowNew()," + "`n" + "flowOld:()=>{const G6=")
$js2 = Rep $js2 "S('Arus Global $dash Performa Relatif','Global Flow $dash Relative Performance')" "S('Performa Relatif (Yahoo)','Relative Performance (Yahoo)')"
$js2 = Rep $js2 "window.v7={sel:(k,v)=>" "window.v7={ftf:k=>{NV.ftf=k;rd()},fxr:()=>{window.rdLoad(true);fxLoad()},sel:(k,v)=>"
if ($js2.Contains('</script>')) { throw 'Kode baru mengandung </script>' }
$tag = '<script id="v8-js">'
$i = $ht.IndexOf($tag); if ($i -lt 0) { throw 'Tag <script id="v8-js"> tidak ditemukan di index.html' }
$s = $i + $tag.Length
$e = $ht.IndexOf('</script>',$s); if ($e -lt 0) { throw 'Penutup </script> tidak ditemukan' }
$old = $ht.Substring($s,$e-$s)
if ($old.Trim() -ne $js.Trim()) { throw 'Blok v8-js di index.html TIDAK sama dengan tools\v8.js. Tidak ada yang diubah.' }
$lead = $old.Substring(0,$old.Length-$old.TrimStart().Length)
$trail = $old.Substring($old.TrimEnd().Length)
$ht2 = $ht.Substring(0,$s) + $lead + $js2.Trim() + $trail + $ht.Substring($e)
Copy-Item $jsPath "$env:TEMP\v8.js.v9.bak" -Force
Copy-Item $htPath "$env:TEMP\index.html.v9.bak" -Force
$u8 = New-Object Text.UTF8Encoding($false)
[IO.File]::WriteAllText($jsPath,$js2,$u8)
[IO.File]::WriteAllText($htPath,$ht2,$u8)
"v8.js: $((Get-Item $jsPath).Length) byte; index.html: $((Get-Item $htPath).Length) byte"
"flowNew di v8.js: $(([regex]::Matches([IO.File]::ReadAllText($jsPath),'function flowNew')).Count); di index.html: $(([regex]::Matches([IO.File]::ReadAllText($htPath),'function flowNew')).Count)"
if (Get-Command node -ErrorAction SilentlyContinue) { node --check $jsPath; "node --check v8.js: kode keluar $LASTEXITCODE" }
'Selesai.'
